import { createDirectus, rest, staticToken, createItem } from '@directus/sdk';

const directus = createDirectus(process.env.DIRECTUS_URL || 'http://directus:8055')
  .with(staticToken(process.env.DIRECTUS_STATIC_TOKEN || ''))
  .with(rest());

export function trackLLMCall(meta: any) {
  setImmediate(async () => {
    try {
      await directus.request(createItem('llm_telemetry_logs', meta));
    } catch (e) {
      console.error('[Telemetry] Error:', e.message);
    }
  });
}

