import Redis from 'ioredis';
const redis = new Redis(process.env.VALKEY_URL || 'redis://cache:6379');

export async function checkHealth() {
  const res = await fetch('http://nats:8222/varz', { signal: AbortSignal.timeout(3000) });
  const varz = await res.json();
  const dlq = await redis.llen('bull:dlq:failed').catch(() => 0);
  return { natsConnections: varz.connections, dlqDepth: dlq };
}
